import { useEffect, useRef, type ReactNode } from "react"
import { cn } from "@/lib/utils"

type Props = {
  /** Left cluster — nav / mode icon buttons (no breadcrumbs). */
  toolbarStart?: ReactNode
  /** Right cluster — secondary actions. */
  toolbarEnd?: ReactNode
  /** Hide the toolbar row when both clusters are empty. */
  hideToolbarWhenEmpty?: boolean
  /** Classes for the scroll/body region under the toolbar. */
  bodyClassName?: string
  children?: ReactNode
  className?: string
  scrollTop?: number
  onScrollTopChange?: (scrollTop: number) => void
}

/**
 * Controller chrome inside AdminView: optional toolbar (nav buttons) + body.
 * Breadcrumbs / sidebar collapse live on AdminView, not here.
 */
export function ControllerView({
  toolbarStart,
  toolbarEnd,
  hideToolbarWhenEmpty = true,
  bodyClassName,
  children,
  className,
  scrollTop,
  onScrollTopChange,
}: Props) {
  const hasToolbar = toolbarStart != null || toolbarEnd != null
  const showToolbar = hasToolbar || !hideToolbarWhenEmpty
  const bodyRef = useRef<HTMLDivElement>(null)
  const scrollTimerRef = useRef<number | null>(null)
  const onScrollTopChangeRef = useRef(onScrollTopChange)
  onScrollTopChangeRef.current = onScrollTopChange

  useEffect(() => {
    const element = bodyRef.current
    if (!element || scrollTop == null) return
    const frame = window.requestAnimationFrame(() => {
      if (bodyRef.current) bodyRef.current.scrollTop = scrollTop
    })
    return () => window.cancelAnimationFrame(frame)
  }, [scrollTop])

  useEffect(() => {
    const element = bodyRef.current
    return () => {
      if (scrollTimerRef.current != null) window.clearTimeout(scrollTimerRef.current)
      if (element && onScrollTopChangeRef.current) {
        onScrollTopChangeRef.current(element.scrollTop)
      }
    }
  }, [])

  return (
    <div className={cn("flex h-full min-h-0 min-w-0 max-w-full flex-col", className)}>
      {showToolbar ? (
        <header data-slot="controller-toolbar" className="flex min-h-8 shrink-0 flex-wrap items-center justify-between gap-1.5 border-b border-border px-2 py-1">
          <div className="flex min-w-0 max-w-full flex-wrap items-center gap-1 [&_[data-slot=button]]:h-6! [&_[data-slot=button]]:px-2! [&_[data-slot=select-trigger]]:h-6! [&_[data-slot=toggle-group-item]]:h-6!">
            {toolbarStart}
          </div>
          <div className="flex min-w-0 max-w-full flex-wrap items-center gap-1 [&_[data-slot=button]]:h-6! [&_[data-slot=button]]:px-2! [&_[data-slot=select-trigger]]:h-6! [&_[data-slot=toggle-group-item]]:h-6!">
            {toolbarEnd}
          </div>
        </header>
      ) : null}
      <div
        data-slot="controller-body"
        ref={bodyRef}
        onScroll={(event) => {
          if (!onScrollTopChangeRef.current) return
          if (scrollTimerRef.current != null) window.clearTimeout(scrollTimerRef.current)
          const next = event.currentTarget.scrollTop
          scrollTimerRef.current = window.setTimeout(() => {
            onScrollTopChangeRef.current?.(next)
          }, 150)
        }}
        className={cn(
          "min-h-0 min-w-0 flex-1 overflow-y-auto",
          bodyClassName,
        )}
      >
        {children}
      </div>
    </div>
  )
}
