import { useCallback, useMemo, type ReactNode } from "react"
import { SettingsFieldRow } from "@/components/settings-form/SettingsFieldRow"
import { SettingsSection } from "@/components/settings-form/SettingsSection"
import { FieldGroup } from "@/components/ui/field"
import { getByPath, setByPath } from "@/lib/settings-form/path"
import type {
  SettingsFieldContext,
  SettingsField,
  SettingsFormSchema,
  SettingsSectionField,
} from "@/lib/settings-form/types"
import { cn } from "@/lib/utils"

type Props = {
  schema: SettingsFormSchema
  values: Record<string, unknown>
  onChange: (next: Record<string, unknown>) => void
  className?: string
  leading?: ReactNode
  trailing?: ReactNode
}

type FieldBlock =
  | { kind: "fields"; fields: SettingsField[] }
  | { kind: "section"; section: SettingsSectionField; fields: SettingsField[] }

function groupFields(fields: SettingsField[]): FieldBlock[] {
  const blocks: FieldBlock[] = []
  let current: FieldBlock = { kind: "fields", fields: [] }
  blocks.push(current)
  for (const field of fields) {
    if (field.type === "section") {
      current = { kind: "section", section: field, fields: [] }
      blocks.push(current)
    } else {
      current.fields.push(field)
    }
  }
  return blocks
}

function fieldKey(field: SettingsField): string {
  return "path" in field ? (field.id ?? field.path) : field.id
}

/** Group by schema order before visibility, so hidden parents still separate runs. */
function SettingsFields({ fields, ctx }: { fields: SettingsField[]; ctx: SettingsFieldContext }) {
  const runs: Array<{ indented: boolean; fields: SettingsField[] }> = []
  for (const field of fields) {
    const indented = "indent" in field && field.indent === true
    const previous = runs[runs.length - 1]
    if (indented && previous?.indented) previous.fields.push(field)
    else runs.push({ indented, fields: [field] })
  }
  return runs.map(run => {
    if (!run.indented) {
      const field = run.fields[0]
      return <SettingsFieldRow key={fieldKey(field)} field={field} ctx={ctx} />
    }
    if (!run.fields.some(field => !field.visible || field.visible(ctx.values))) return null
    return <div key={`dependent:${fieldKey(run.fields[0])}`} data-slot="settings-dependent-fields"
      className="ml-2 flex min-w-0 flex-col gap-4 border-l-2 border-border pl-4 empty:hidden">
      {run.fields.map(field => <SettingsFieldRow key={fieldKey(field)}
        field={"indent" in field ? { ...field, indent: false } : field} ctx={ctx} />)}
    </div>
  })
}

/**
 * Declarative settings form: renders schema fields + `type: "custom"` escape hatches.
 * Values are a plain nested object (typically a slice of map options).
 */
export function SettingsForm({ schema, values, onChange, className, leading, trailing }: Props) {
  const setValue = useCallback(
    (path: string, value: unknown) => {
      onChange(setByPath(values, path, value))
    },
    [onChange, values],
  )

  const setValues = useCallback(
    (next: Record<string, unknown>) => {
      onChange(next)
    },
    [onChange],
  )

  const ctx: SettingsFieldContext = useMemo(
    () => ({
      values,
      getValue: (path) => getByPath(values, path),
      setValue,
      setValues,
    }),
    [values, setValue, setValues],
  )

  return (
    <form
      data-slot="settings-form"
      className={cn("min-w-0 w-full max-w-full p-3 [overflow-wrap:anywhere] [&_[data-slot=select-trigger]]:min-w-0 [&_[data-slot=select-trigger]]:max-w-full [&_[data-slot=select-value]]:min-w-0 [&_[data-slot=select-value]]:truncate", className)}
      onSubmit={(e) => e.preventDefault()}
    >
      <FieldGroup className="gap-4">
        {leading}
        {groupFields(schema.fields).map((block) => block.kind === "fields" ? (
          <SettingsFields key="before-sections" fields={block.fields} ctx={ctx} />
        ) : (
          <SettingsSection
            key={block.section.id}
            title={block.section.label}
            help={block.section.help}
            headerVisible={!block.section.visible || block.section.visible(values)}
          >
            <SettingsFields fields={block.fields} ctx={ctx} />
          </SettingsSection>
        ))}
        {trailing}
      </FieldGroup>
    </form>
  )
}
