import type { ReactNode } from "react"
import {
  Field,
  FieldContent,
  FieldDescription,
  FieldLabel,
} from "@/components/ui/field"
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert"
import {
  InputGroup,
  InputGroupAddon,
  InputGroupInput,
  InputGroupText,
} from "@/components/ui/input-group"
import { Input } from "@/components/ui/input"
import { ColorInput } from "@/components/settings-form/ColorInput"
import { Checkbox } from "@/components/ui/checkbox"
import { Label } from "@/components/ui/label"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { ChoiceRadioGroup } from "@/components/settings-form/ChoiceRadioGroup"
import { SettingsPositionGrid } from "./SettingsPositionGrid"
import { SettingsNumberSlider, SettingsRangeControl } from "./SettingsSliderControl"
import { getByPath } from "@/lib/settings-form/path"
import type {
  SettingsAlertField,
  SettingsField,
  SettingsFieldContext,
  SettingsGroupField,
  SettingsInlineInputField,
  SettingsNumberField,
  SettingsOption,
  SettingsPositionGridField,
} from "@/lib/settings-form/types"
import { cn } from "@/lib/utils"
import { SettingsBooleanField, SettingsControlField } from "./SettingsControlField"
import { SettingsSectionHeader } from "@/components/settings-form/SettingsSectionHeader"

function fieldId(field: SettingsField): string {
  if (
    field.type === "custom" ||
    field.type === "section" ||
    field.type === "group" ||
    field.type === "alert"
  ) {
    return field.id
  }
  return field.id ?? field.path
}

function isDisabled(
  field: Exclude<SettingsField, { type: "section" | "group" | "alert" }>,
  values: Record<string, unknown>,
): boolean {
  if (typeof field.disabled === "function") return field.disabled(values)
  return Boolean(field.disabled)
}

function parseNumberInput(
  raw: string,
  field: SettingsNumberField,
): number | string | "" {
  if (raw === "" && field.allowEmpty) return ""
  if (raw === "") return field.allowEmpty ? "" : 0
  const n = field.integer ? parseInt(raw, 10) : parseFloat(raw)
  if (Number.isNaN(n)) return raw
  let v = n
  if (field.min != null) v = Math.max(field.min, v)
  if (field.max != null) v = Math.min(field.max, v)
  return v
}

function NumberOrTextControl({
  field,
  ctx,
  disabled,
}: {
  field: SettingsNumberField | Extract<SettingsField, { type: "text" }>
  ctx: SettingsFieldContext
  disabled: boolean
}) {
  const raw = getByPath(ctx.values, field.path)
  const display =
    raw === undefined || raw === null ? "" : String(raw as string | number)

  const input = (
    <InputGroupInput
      id={fieldId(field)}
      disabled={disabled}
      placeholder={field.placeholder}
      value={display}
      onChange={(e) => {
        if (field.type === "number") {
          ctx.setValue(field.path, parseNumberInput(e.target.value, field))
        } else {
          ctx.setValue(field.path, e.target.value)
        }
      }}
    />
  )

  if (field.suffix) {
    return (
      <InputGroup>
        {input}
        <InputGroupAddon align="inline-end">
          <InputGroupText>{field.suffix}</InputGroupText>
        </InputGroupAddon>
      </InputGroup>
    )
  }

  return (
    <Input
      id={fieldId(field)}
      disabled={disabled}
      placeholder={field.placeholder}
      value={display}
      onChange={(e) => {
        if (field.type === "number") {
          ctx.setValue(field.path, parseNumberInput(e.target.value, field))
        } else {
          ctx.setValue(field.path, e.target.value)
        }
      }}
    />
  )
}

function InlineInputControl({
  field,
  ctx,
}: {
  field: SettingsInlineInputField
  ctx: SettingsFieldContext
}) {
  const disabled = isDisabled(field, ctx.values)
  const raw = getByPath(ctx.values, field.path)
  const display =
    raw === undefined || raw === null ? "" : String(raw as string | number)

  return (
    <InputGroup>
      <InputGroupAddon align="inline-start">
        <InputGroupText className="min-w-4 justify-center font-medium text-foreground/60">
          {field.shortLabel}
        </InputGroupText>
      </InputGroupAddon>
      <InputGroupInput
        id={fieldId(field)}
        aria-label={field.label ?? field.shortLabel}
        disabled={disabled}
        placeholder={field.placeholder}
        value={display}
        onChange={(event) => {
          if (field.type === "number") {
            ctx.setValue(field.path, parseNumberInput(event.target.value, field))
          } else {
            ctx.setValue(field.path, event.target.value)
          }
        }}
      />
      {field.suffix ? (
        <InputGroupAddon align="inline-end">
          <InputGroupText>{field.suffix}</InputGroupText>
        </InputGroupAddon>
      ) : null}
    </InputGroup>
  )
}

function SettingsPositionGridRow({
  field,
  ctx,
}: {
  field: SettingsPositionGridField
  ctx: SettingsFieldContext
}) {
  const disabled = isDisabled(field, ctx.values)
  const value = String(getByPath(ctx.values, field.path) ?? "")

  return (
    <Field orientation="vertical" data-disabled={disabled || undefined}>
      {field.label ? (
        <FieldLabel
          data-role="settings-input-label"
          className="text-[11px] leading-4 font-normal text-foreground/55"
        >
          {field.label}
        </FieldLabel>
      ) : null}
      <FieldContent>
        <SettingsPositionGrid value={value} options={field.options} disabled={disabled}
          onValueChange={position => ctx.setValue(field.path, position)} />
        {field.help ? <FieldDescription>{field.help}</FieldDescription> : null}
      </FieldContent>
    </Field>
  )
}

function SettingsInputGroupRow({
  field,
  ctx,
}: {
  field: SettingsGroupField
  ctx: SettingsFieldContext
}) {
  const visibleFields = field.fields.filter(
    (item) => !item.visible || item.visible(ctx.values),
  )
  if (visibleFields.length === 0) return null

  const columns = Math.max(1, field.columns ?? visibleFields.length)

  return (
    <Field orientation="vertical">
      {field.label ? <FieldLabel
        data-role="settings-input-label"
        className="text-[11px] leading-4 font-normal text-foreground/55"
      >
        {field.label}
      </FieldLabel> : null}
      <FieldContent>
        <div
          data-slot="settings-inline-group"
          className="grid gap-2"
          style={{
            gridTemplateColumns: `repeat(${columns}, minmax(0, 1fr))`,
          }}
        >
          {visibleFields.map((item) => field.inputLabels === "above" ? (
            <SettingsFieldRow key={item.id ?? item.path} field={item} ctx={ctx} />
          ) : (
            <InlineInputControl
              key={item.id ?? item.path}
              field={item}
              ctx={ctx}
            />
          ))}
        </div>
        {field.help ? <FieldDescription>{field.help}</FieldDescription> : null}
      </FieldContent>
    </Field>
  )
}

function OptionHelp({ help }: { help?: string }) {
  if (!help) return null
  return <FieldDescription>{help}</FieldDescription>
}

function CheckboxOptions({
  options,
  name,
  values,
  disabled,
  onChange,
}: {
  options: SettingsOption[]
  name: string
  values: string[]
  disabled: boolean
  onChange: (next: string[]) => void
}) {
  return (
    <div className="grid gap-3">
      {options.map((opt) => {
        const optId = `${name}-${opt.value}`
        const checked = values.includes(opt.value)
        return (
          <div key={opt.value} className="flex gap-3">
            <Checkbox
              id={optId}
              checked={checked}
              disabled={disabled}
              onCheckedChange={(state) => {
                const on = state === true
                if (on) onChange([...values, opt.value])
                else onChange(values.filter((v) => v !== opt.value))
              }}
            />
            <div className="grid min-w-0 flex-1 gap-1.5 leading-none">
              <Label htmlFor={optId} className="font-normal">
                {opt.label}
              </Label>
              <OptionHelp help={opt.help} />
            </div>
          </div>
        )
      })}
    </div>
  )
}

function SettingsAlertRow({
  field,
  values,
}: {
  field: SettingsAlertField
  values: Record<string, unknown>
}) {
  if (field.visible && !field.visible(values)) return null
  return (
    <Alert variant={field.variant ?? "info"}>
      {field.title ? <AlertTitle>{field.title}</AlertTitle> : null}
      <AlertDescription
        dangerouslySetInnerHTML={{ __html: field.html }}
      />
    </Alert>
  )
}

type Props = {
  field: SettingsField
  ctx: SettingsFieldContext
}

export function SettingsFieldRow({
  field,
  ctx,
}: Props) {
  if (field.visible && !field.visible(ctx.values)) return null

  if (field.type === "alert") {
    return <SettingsAlertRow field={field} values={ctx.values} />
  }

  if (field.type === "section") {
    return (
      <SettingsSectionHeader help={field.help}>
        {field.label}
      </SettingsSectionHeader>
    )
  }

  if (field.type === "group") {
    return <SettingsInputGroupRow field={field} ctx={ctx} />
  }

  if (field.type === "position-grid") {
    return <SettingsPositionGridRow field={field} ctx={ctx} />
  }

  if (field.type === "custom") {
    return <>{field.render(ctx)}</>
  }

  const disabled = isDisabled(field, ctx.values)
  const id = fieldId(field)
  const indentClass = field.indent ? "pl-6" : undefined

  // Boolean settings keep `type: "switch"` in schemas, but their visual
  // control is globally swappable for quick UX experiments.
  if (field.type === "switch") {
    const checked = Boolean(getByPath(ctx.values, field.path))

    return <SettingsBooleanField id={id} label={field.label} help={field.help}
      disabled={disabled} className={indentClass} checked={checked}
      onCheckedChange={value => ctx.setValue(field.path, value)} />
  }

  // Checkbox: control left, label (+ help) right — Actions-style
  if (field.type === "checkbox") {
    const checked = Boolean(getByPath(ctx.values, field.path))
    return (
      <Field
        orientation="horizontal"
        data-disabled={disabled || undefined}
        className={cn("items-start", indentClass)}
      >
        <Checkbox
          id={id}
          checked={checked}
          disabled={disabled}
          className="mt-0.5"
          onCheckedChange={(state) => ctx.setValue(field.path, state === true)}
        />
        <FieldContent className="translate-y-px">
          {field.label ? (
            <FieldLabel htmlFor={id} className="font-normal">
              {field.label}
            </FieldLabel>
          ) : null}
          {field.help ? (
            <FieldDescription>{field.help}</FieldDescription>
          ) : null}
        </FieldContent>
      </Field>
    )
  }

  let control: ReactNode = null

  if ((field.type === "select" || field.type === "radio") && field.options.length > 0 && field.options.length <= 3) {
    control = <ChoiceRadioGroup id={id} aria-label={field.label}
      options={field.options.map((option) => ({ ...option, help: <OptionHelp help={option.help} /> }))}
      value={String(getByPath(ctx.values, field.path) ?? "")} disabled={disabled}
      onValueChange={(value) => ctx.setValue(field.path, value)} />
  } else if (field.type === "select" || field.type === "radio") {
    const value = String(getByPath(ctx.values, field.path) ?? "")
    control = (
      <Select
        value={value || undefined}
        disabled={disabled}
        onValueChange={(v) => ctx.setValue(field.path, v)}
      >
        <SelectTrigger id={id} className="w-full">
          <SelectValue placeholder={("placeholder" in field ? field.placeholder : undefined) ?? "Select…"} />
        </SelectTrigger>
        <SelectContent>
          {field.options.map((opt) => (
            <SelectItem key={opt.value} value={opt.value}>
              {opt.label}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
    )
  } else if (field.type === "checkboxes") {
    const raw = getByPath(ctx.values, field.path)
    const selected = Array.isArray(raw) ? (raw as string[]) : []
    control = (
      <CheckboxOptions
        name={id}
        options={field.options}
        values={selected}
        disabled={disabled}
        onChange={(next) => ctx.setValue(field.path, next)}
      />
    )
  } else if (field.type === "color") {
    control = <ColorInput id={id} label={field.label ?? "Color"}
      value={String(getByPath(ctx.values, field.path) ?? "")}
      placeholder={field.placeholder} disabled={disabled}
      onChange={(value) => ctx.setValue(field.path, value)} />
  } else if (field.type === "range") {
    control = <SettingsRangeControl field={field} value={getByPath(ctx.values, field.path)} disabled={disabled}
      onChange={value => ctx.setValue(field.path, value)} />
  } else if (field.type === "number" && field.slider) {
    control = <SettingsNumberSlider field={field} value={getByPath(ctx.values, field.path)} disabled={disabled}
      onChange={value => ctx.setValue(field.path, value)} />
  } else if (field.type === "text" || field.type === "number") {
    control = (
      <NumberOrTextControl field={field} ctx={ctx} disabled={disabled} />
    )
  }

  return (
    <SettingsControlField id={id} label={field.label} help={field.help}
      disabled={disabled} className={indentClass}>
      {control}
    </SettingsControlField>
  )
}
