import type { ReactNode } from "react"
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip"
import { cn } from "@/lib/utils"
import { ABSOLUTE_ANCHORS } from "../../../../mapsvg/Layout/ResponsiveLayout"

const DOT: Record<string, string> = {
  "top-left": "left-0 top-0", top: "left-1/2 top-0 -translate-x-1/2", "top-right": "right-0 top-0",
  left: "left-0 top-1/2 -translate-y-1/2", center: "left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2", right: "right-0 top-1/2 -translate-y-1/2",
  "bottom-left": "bottom-0 left-0", bottom: "bottom-0 left-1/2 -translate-x-1/2", "bottom-right": "bottom-0 right-0",
}

/** Shared 3×3 picker. Callers can omit unsupported positions (legacy center). */
export function SettingsPositionGrid({ value, options, disabled, onValueChange, "aria-label": label }: {
  value: string
  options: Array<{ value: string; label: ReactNode }>
  disabled?: boolean
  onValueChange: (value: string) => void
  "aria-label"?: string
}) {
  const byValue = new Map(options.map(option => [option.value, option]))
  return <div data-slot="settings-position-grid" role="group" aria-label={label} className="grid w-fit grid-cols-3 gap-0.5">
    {ABSOLUTE_ANCHORS.map(position => {
      const option = byValue.get(position)
      if (!option) return <button key={position} type="button" disabled aria-label={position === "center" ? "Center unavailable" : position}
        className="size-7 cursor-default rounded-[3px] border border-border bg-muted/35" />
      return <Tooltip key={position}><TooltipTrigger asChild>
        <button type="button" aria-label={typeof option.label === "string" ? option.label : position} aria-pressed={value === position} disabled={disabled}
          className={cn("grid size-7 place-items-center rounded-[3px] border border-border bg-background text-muted-foreground transition-colors duration-100 hover:bg-muted hover:text-foreground", value === position && "border-foreground/25 bg-muted text-foreground")}
          onClick={() => onValueChange(position)}>
          <span className="relative block size-3.5 rounded-[2px] border border-current/30"><span className={cn("absolute size-1.5 rounded-[1px] bg-current", DOT[position])} /></span>
        </button>
      </TooltipTrigger><TooltipContent side="top">{option.label}</TooltipContent></Tooltip>
    })}
  </div>
}
