import { useEffect, useState, type ChangeEvent, type KeyboardEvent } from "react"
import { Input } from "@/components/ui/input"
import { InputGroup, InputGroupAddon, InputGroupInput, InputGroupText } from "@/components/ui/input-group"
import { Slider } from "@/components/ui/slider"
import type { SettingsNumberField, SettingsRangeField } from "@/lib/settings-form/types"

function bounded(value: number, min: number, max: number, step: number): number {
  return Math.min(max, Math.max(min, Number((min + Math.round((value - min) / step) * step).toFixed(8))))
}

function numeric(value: unknown, fallback: number): number {
  return value !== "" && value != null && Number.isFinite(Number(value)) ? Number(value) : fallback
}

/** Incomplete numeric typing stays local; options never receive empty/NaN/"-". */
function SliderNumberInput({ id, label, value, min, max, step, disabled, prefix, onChange }: {
  id: string; label: string; value: number; min: number; max: number; step: number
  disabled?: boolean; prefix?: string; onChange: (value: number) => void
}) {
  const [draft, setDraft] = useState(String(value))
  useEffect(() => setDraft(String(value)), [value])
  const props = {
    id, "aria-label": label, inputMode: "decimal" as const, disabled, value: draft,
    onChange: (event: ChangeEvent<HTMLInputElement>) => {
      const raw = event.target.value
      setDraft(raw)
      if (raw.trim() === "" || !Number.isFinite(Number(raw))) return
      const next = bounded(Number(raw), min, max, step)
      setDraft(String(next))
      if (next !== value) onChange(next)
    },
    onBlur: () => setDraft(String(value)),
    onKeyDown: (event: KeyboardEvent<HTMLInputElement>) => {
      if (event.key === "Escape") { setDraft(String(value)); event.stopPropagation() }
      if (event.key === "Enter") event.currentTarget.blur()
    },
  }
  return prefix ? <InputGroup>
    <InputGroupAddon><InputGroupText>{prefix}</InputGroupText></InputGroupAddon>
    <InputGroupInput {...props} />
  </InputGroup> : <Input {...props} />
}

export function SettingsNumberSlider({ field, value, disabled, onChange }: {
  field: SettingsNumberField; value: unknown; disabled: boolean; onChange: (value: number) => void
}) {
  const min = field.min ?? 0, max = field.max ?? 100, step = field.step ?? 1
  const current = bounded(numeric(value, min), min, max, step)
  const id = field.id ?? field.path, label = field.label ?? field.path
  return <div data-slot="settings-number-slider" className="@container/settings-slider min-w-0">
    <div className="grid min-w-0 grid-cols-1 items-center gap-2 @min-[128px]/settings-slider:grid-cols-[minmax(0,1fr)_3.5rem]">
      <div className="min-w-0 px-2 py-2">
        <Slider min={min} max={max} step={step} value={[current]} disabled={disabled}
          thumbLabels={[`${label} slider`]} onValueChange={values => { if (values[0] !== current) onChange(values[0]) }} />
      </div>
      <SliderNumberInput id={id} label={label} value={current} min={min} max={max} step={step}
        disabled={disabled} onChange={onChange} />
    </div>
  </div>
}

export function SettingsRangeControl({ field, value, disabled, onChange }: {
  field: SettingsRangeField; value: unknown; disabled: boolean; onChange: (value: number[]) => void
}) {
  const { min, max } = field, step = field.step ?? 1
  const raw = Array.isArray(value) ? value : []
  const lower = bounded(numeric(raw[0], min), min, max - step, step)
  const upper = bounded(numeric(raw[1], max), lower + step, max, step)
  const id = field.id ?? field.path
  const lowerLabel = field.lowerLabel ?? `${field.label ?? field.path} minimum`
  const upperLabel = field.upperLabel ?? `${field.label ?? field.path} maximum`
  return <div data-slot="settings-range-slider" className="grid min-w-0 gap-2">
    <div className="min-w-0 px-2 py-2">
      <Slider id={id} min={min} max={max} step={step} minStepsBetweenThumbs={1}
        value={[lower, upper]} disabled={disabled} thumbLabels={[`${lowerLabel} slider`, `${upperLabel} slider`]}
        onValueChange={onChange} />
    </div>
    <div className="grid min-w-0 grid-cols-2 gap-2">
      <SliderNumberInput id={`${id}.minimum`} label={lowerLabel} prefix="Min" value={lower}
        min={min} max={upper - step} step={step} disabled={disabled} onChange={next => onChange([next, upper])} />
      <SliderNumberInput id={`${id}.maximum`} label={upperLabel} prefix="Max" value={upper}
        min={lower + step} max={max} step={step} disabled={disabled} onChange={next => onChange([lower, next])} />
    </div>
  </div>
}
