/** Canonical Components controller tabs (order fixed). */
const COMPONENT_CONTROLLER_MODES = [
  { id: "settings", label: "Settings", icon: Settings2Icon },
  { id: "fields", label: "Fields", icon: ListIcon },
  { id: "interactions", label: "Interactions", icon: MousePointer2Icon },
  { id: "styles", label: "Styles", icon: PaintbrushIcon },
  { id: "code", label: "Code", icon: CodeXmlIcon },
] as const

export type ComponentControllerModeId = (typeof COMPONENT_CONTROLLER_MODES)[number]["id"]
// Accepted for stored pre-Code workspace state and extension callers.
type LegacyCodeMode = "template" | "css" | "js"
type CodeDocument = {
  id: string
  category: "Templates" | "JS" | "CSS"
  label: string
  language: MonacoLanguage
  value: string
  onChange: (next: string) => void
}

import { ComponentInteractionsContext } from "@/components/component-interactions-context"
export { ComponentInteractionsProvider } from "@/components/component-interactions-context"

/** Schema-driven form section (settings / styles). */
export type ComponentSchemaSection = {
  schema: SettingsFormSchema
  values?: Record<string, unknown>
  defaultValues?: Record<string, unknown>
  onChange?: (next: Record<string, unknown>) => void
  /** Functional enable remains separate from profile-scoped Layout visibility. */
  retainEnable?: boolean
}

/** Monaco editor section (single template / css / js). */
export type ComponentCodeSection = {
  value?: string
  defaultValue?: string
  onChange?: (value: string) => void
  language?: MonacoLanguage
}

/** One template key with html/css/js (Popover Region/DB Object, etc.). */
export type ComponentTemplateEntry = {
  id: string
  label: string
  html?: string
  css?: string
  js?: string
  /** Labels render without a controller, so they expose HTML/CSS only. */
  parts?: readonly ("html" | "css" | "js")[]
}

/** Event / middleware script leaf for the JS tab picker. */
export type ComponentScriptEntry = {
  id: string
  label: string
  defaultValue?: string
}

type Props = {
  fields?: ReactNode
  settings?: ComponentSchemaSection
  styles?: ComponentSchemaSection
  /** Single-key editors (Directory, Details View, ProductCard, Core CSS). */
  template?: ComponentCodeSection
  css?: ComponentCodeSection
  js?: ComponentCodeSection
  /**
   * Multi-template sources for the Code picker. Overrides flat template parts.
   */
  templateEntries?: ComponentTemplateEntry[]
  /** Named sources alongside existing flat editors; preserve their source IDs. */
  additionalTemplateEntries?: ComponentTemplateEntry[]
  /** Fired when a multi-template entry html/css/js draft changes. */
  onTemplateEntryChange?: (id: string, next: { html: string; css: string; js: string }) => void
  /**
   * Event and middleware sources for the Code picker; may coexist with templates.
   */
  scriptEntries?: ComponentScriptEntry[]
  /** Fired when a multi-script draft changes. */
  onScriptEntryChange?: (id: string, next: string) => void
  disabled?: Partial<Record<ComponentControllerModeId | LegacyCodeMode, boolean>>
  defaultMode?: ComponentControllerModeId | LegacyCodeMode
  className?: string
  toolbarActions?: ReactNode
  settingsEnd?: ReactNode
}

function useControllableRecord(section: ComponentSchemaSection | undefined): {
  values: Record<string, unknown>
  setValues: (next: Record<string, unknown>) => void
} {
  const [local, setLocal] = useState<Record<string, unknown>>(() => section?.defaultValues ?? {})
  const controlled = section?.values !== undefined
  const values = controlled ? (section.values as Record<string, unknown>) : local
  const setValues = (next: Record<string, unknown>) => {
    if (!controlled) setLocal(next)
    section?.onChange?.(next)
  }
  return { values, setValues }
}

function useControllableString(section: ComponentCodeSection | undefined): {
  value: string
  setValue: (next: string) => void
} {
  const [local, setLocal] = useState(() => section?.defaultValue ?? "")
  const controlled = section?.value !== undefined
  const value = controlled ? (section.value as string) : local
  const setValue = (next: string) => {
    if (!controlled) setLocal(next)
    section?.onChange?.(next)
  }
  return { value, setValue }
}

/**
 * Shared Components controller: settings / styles (SettingsForm) +
 * Code (one Monaco editor with an independently owned model per source).
 */
export function ComponentController({
  settings,
  fields,
  styles,
  template,
  css,
  js,
  templateEntries,
  additionalTemplateEntries,
  onTemplateEntryChange,
  scriptEntries,
  onScriptEntryChange,
  disabled,
  defaultMode = "settings",
  className,
  toolbarActions,
  settingsEnd,
}: Props) {
  const interactions = useContext(ComponentInteractionsContext)
  const map = useAdminMap()
  const mapId = map?.id ? Number(map.id) : null
  const session = useWorkspaceStore((state) =>
    mapId ? state.mapSessions[String(mapId)] : undefined,
  )
  const patchMapSession = useWorkspaceStore((state) => state.patchMapSession)
  const setMapScroll = useWorkspaceStore((state) => state.setMapScroll)
  const settingsState = useControllableRecord(settings)
  const stylesState = useControllableRecord(styles)
  const templateState = useControllableString(template)
  const cssState = useControllableString(css)
  const jsState = useControllableString(js)

  const hasTemplateEntries = (templateEntries?.length ?? 0) > 0
  const allTemplateEntries = [...(templateEntries ?? []), ...(additionalTemplateEntries ?? [])]
  const hasScriptEntries = (scriptEntries?.length ?? 0) > 0

  const legacyTemplateKey =
    session?.componentTemplateKey &&
    templateEntries?.some((entry) => entry.id === session.componentTemplateKey)
      ? session.componentTemplateKey
      : (templateEntries?.[0]?.id ?? "")
  const legacyScriptKey =
    session?.componentScriptKey &&
    scriptEntries?.some((entry) => entry.id === session.componentScriptKey)
      ? session.componentScriptKey
      : (scriptEntries?.[0]?.id ?? "")

  const [entryDrafts, setEntryDrafts] = useState<
    Record<string, { html: string; css: string; js: string }>
  >(() => {
    const init: Record<string, { html: string; css: string; js: string }> = {}
    for (const e of allTemplateEntries) {
      init[e.id] = {
        html: e.html ?? "",
        css: e.css ?? "",
        js: e.js ?? "",
      }
    }
    return init
  })

  const [scriptDrafts, setScriptDrafts] = useState<Record<string, string>>(() => {
    const init: Record<string, string> = {}
    for (const e of scriptEntries ?? []) {
      init[e.id] = e.defaultValue ?? ""
    }
    return init
  })

  const patchEntry = (id: string, patch: Partial<{ html: string; css: string; js: string }>) => {
    const entry = allTemplateEntries.find((entry) => entry.id === id)
    const current = entryDrafts[id] ?? {
      html: entry?.html ?? "",
      css: entry?.css ?? "",
      js: entry?.js ?? "",
    }
    const next = { ...current, ...patch }
    setEntryDrafts((prev) => ({ ...prev, [id]: next }))
    onTemplateEntryChange?.(id, next)
  }

  const patchScript = (id: string, next: string) => {
    setScriptDrafts((prev) => ({ ...prev, [id]: next }))
    onScriptEntryChange?.(id, next)
  }

  const documents: CodeDocument[] = []
  for (const [part, category, language] of [
    ["html", "Templates", "handlebars"],
    ["js", "JS", "javascript"],
    ["css", "CSS", "css"],
  ] as const) {
    const legacyMode = part === "html" ? "template" : part
    if (disabled?.[legacyMode]) continue
    if (hasTemplateEntries) {
      for (const entry of templateEntries!) {
        if (entry.parts && !entry.parts.includes(part)) continue
        const label =
          templateEntries!.length === 1
            ? part === "html"
              ? "main"
              : part === "js"
                ? "afterRender"
                : "styles"
            : part === "html"
              ? entry.label
              : `${entry.label} ${part === "js" ? "afterRender" : "styles"}`
        documents.push({
          id: `template:${entry.id}:${part}`,
          category,
          label,
          language,
          value: entryDrafts[entry.id]?.[part] ?? entry[part] ?? "",
          onChange: (next) => patchEntry(entry.id, { [part]: next }),
        })
      }
    } else {
      const section = part === "html" ? template : part === "js" ? js : css
      const state = part === "html" ? templateState : part === "js" ? jsState : cssState
      if (section)
        documents.push({
          id: `flat:${part}`,
          category,
          label: part === "html" ? "main" : part === "js" ? "afterRender" : "styles",
          language: section.language ?? language,
          value: state.value,
          onChange: state.setValue,
        })
    }
    for (const entry of additionalTemplateEntries ?? []) {
      if (entry.parts && !entry.parts.includes(part)) continue
      documents.push({
        id: `template:${entry.id}:${part}`,
        category,
        label: part === "html" ? entry.label : `${entry.label} ${part === "js" ? "afterRender" : "styles"}`,
        language,
        value: entryDrafts[entry.id]?.[part] ?? entry[part] ?? "",
        onChange: (next) => patchEntry(entry.id, { [part]: next }),
      })
    }
    if (part === "js")
      for (const entry of scriptEntries ?? [])
        documents.push({
          id: `script:${entry.id}`,
          category,
          label: entry.label.replace(/ @(event|middleware)$/, ""),
          language,
          value: scriptDrafts[entry.id] ?? entry.defaultValue ?? "",
          onChange: (next) => patchScript(entry.id, next),
        })
  }
  const [localDocument, setLocalDocument] = useState("")
  const legacyMode = session?.componentMode ?? defaultMode
  const legacyDocumentId =
    legacyMode === "template" || legacyMode === "css" || legacyMode === "js"
      ? hasTemplateEntries
        ? `template:${legacyTemplateKey}:${legacyMode === "template" ? "html" : legacyMode}`
        : legacyMode === "js" && hasScriptEntries
          ? `script:${legacyScriptKey}`
          : `flat:${legacyMode === "template" ? "html" : legacyMode}`
      : ""
  const requestedDocument = session?.componentCodeDocument ?? (localDocument || legacyDocumentId)
  const activeDocument = documents.find((doc) => doc.id === requestedDocument) ?? documents[0]

  const present: Record<ComponentControllerModeId, boolean> = {
    settings: settings != null,
    fields: fields != null,
    interactions: interactions?.body != null,
    styles: styles != null,
    code: documents.length > 0,
  }
  const availableModes = COMPONENT_CONTROLLER_MODES.filter(
    ({ id }) => present[id] && !disabled?.[id],
  )

  const initialMode =
    availableModes.find(
      (m) => m.id === (["template", "css", "js"].includes(defaultMode) ? "code" : defaultMode),
    )?.id ??
    availableModes[0]?.id ??
    "settings"

  const [localMode, setLocalMode] = useState<ComponentControllerModeId>(initialMode)
  const storedMode = mapId ? session?.componentMode : localMode
  const requestedMode =
    storedMode && ["template", "css", "js"].includes(storedMode) ? "code" : storedMode
  const activeMode =
    requestedMode && availableModes.some((m) => m.id === requestedMode)
      ? requestedMode
      : initialMode

  const isCodeMode = activeMode === "code"
  const documentFeature = (doc: CodeDocument) => doc.category === "Templates" ? "templates" : doc.category === "JS" ? "javascript" : "css"
  const lockedFeature = activeDocument && !hasProductFeature(documentFeature(activeDocument)) ? documentFeature(activeDocument) : null
  const presetMode = isCodeMode && lockedFeature === "templates"

  let body: ReactNode = null
  if (activeMode === "settings" && settings) {
    body = (
      <SettingsForm
        schema={
          interactions?.settingsLead && !settings.retainEnable
            ? {
                ...settings.schema,
                fields: settings.schema.fields.filter(
                  (field) => !("path" in field && field.path === "on"),
                ),
              }
            : settings.schema
        }
        values={settingsState.values}
        onChange={settingsState.setValues}
        leading={interactions?.settingsLead}
        trailing={settingsEnd ?? interactions?.settingsEnd}
      />
    )
  } else if (activeMode === "fields") {
    body = fields
  } else if (activeMode === "interactions" && interactions) {
    body = interactions.body
  } else if (activeMode === "styles" && styles) {
    body = (
      <SettingsForm
        schema={styles.schema}
        values={stylesState.values}
        onChange={stylesState.setValues}
      />
    )
  } else if (isCodeMode && activeDocument) {
    body = presetMode ? (
      <div className="h-full overflow-auto">
        <div className="p-3"><SettingsControlField label="Template">
          <SettingsChoice aria-label="Template preset"
            value={Object.entries(BUILTIN_TEMPLATE_HTML).find(([, html]) => html === activeDocument.value)?.[0] ?? ""}
            placeholder="Current template" options={BUILTIN_TEMPLATE_OPTIONS}
            onValueChange={id => {
              const html = BUILTIN_TEMPLATE_HTML[id as keyof typeof BUILTIN_TEMPLATE_HTML]
              if (html !== undefined) activeDocument.onChange(html)
            }} />
        </SettingsControlField></div>
        <ProductFeaturePlaceholder feature="templates" compact />
      </div>
    ) : lockedFeature ? <ProductFeaturePlaceholder feature={lockedFeature} /> : (
      <MonacoCodeEditor
        documentId={activeDocument.id}
        language={activeDocument.language}
        value={activeDocument.value}
        onChange={activeDocument.onChange}
      />
    )
  }

  if (availableModes.length === 0) {
    return (
      <p className="p-3 text-sm text-muted-foreground">
        No sections configured for this component.
      </p>
    )
  }

  const codeToolbarEnd =
    isCodeMode && activeDocument ? (
      // Source selection must not lock/aria-hide the WordPress page and Monaco.
      <DropdownMenu modal={false}>
        <DropdownMenuTrigger asChild>
          <Button
            variant="outline"
            size="xs"
            aria-label="Code source"
            className="max-w-full min-w-0 gap-1.5 font-normal"
          >
            <span className="text-muted-foreground">{activeDocument.category}</span>
            <span className="text-muted-foreground">·</span>
            <span className="truncate">{activeDocument.label}</span>
            <ChevronDownIcon className="size-3.5 shrink-0 text-muted-foreground" />
          </Button>
        </DropdownMenuTrigger>
        <DropdownMenuContent align="end" className="max-h-[min(70vh,28rem)] overflow-y-auto">
          {(["Templates", "JS", "CSS"] as const).map((category) => {
            const entries = documents.filter((doc) => doc.category === category)
            if (!entries.length) return null
            return (
              <DropdownMenuGroup key={category} aria-label={category}>
                <DropdownMenuLabel className="py-1 text-xs text-muted-foreground">
                  {category}
                </DropdownMenuLabel>
                <DropdownMenuRadioGroup
                  value={activeDocument.id}
                  onValueChange={(id) => {
                    setLocalDocument(id)
                    if (mapId) patchMapSession(mapId, { componentCodeDocument: id })
                  }}
                >
                  {entries.map((doc) => (
                    <DropdownMenuRadioItem key={doc.id} value={doc.id} className="py-1 text-xs">
                      {doc.label}
                      {!hasProductFeature(documentFeature(doc)) ? <PremiumBadge className="ml-3" /> : null}
                    </DropdownMenuRadioItem>
                  ))}
                </DropdownMenuRadioGroup>
              </DropdownMenuGroup>
            )
          })}
        </DropdownMenuContent>
      </DropdownMenu>
    ) : null

  const toolbarEnd =
    activeMode === "interactions" ? (interactions?.toolbarEnd ?? null) : codeToolbarEnd

  const settingsOnly = availableModes.length === 1 && availableModes[0].id === "settings"

  return (
    <ControllerView
      className={cn(className)}
      bodyClassName={isCodeMode ? "overflow-hidden p-0" : undefined}
      toolbarStart={
        settingsOnly ? null : (
          <ToggleGroup
            type="single"
            variant="outline"
            size="sm"
            spacing={1}
            value={activeMode}
            onValueChange={(next) => {
              if (!next) return
              const nextMode = next as ComponentControllerModeId
              setLocalMode(nextMode)
              if (mapId) {
                patchMapSession(mapId, { componentMode: nextMode })
              }
            }}
            className="min-w-0 max-w-full flex-wrap justify-start"
          >
            {availableModes.map(({ id, label, icon: Icon }) => (
              <Tooltip key={id}>
                <TooltipTrigger asChild>
                  <span className="inline-flex">
                    <ToggleGroupItem value={id} aria-label={label} className="size-6 p-0">
                      <Icon />
                    </ToggleGroupItem>
                  </span>
                </TooltipTrigger>
                <TooltipContent side="bottom">{label}</TooltipContent>
              </Tooltip>
            ))}
          </ToggleGroup>
        )
      }
      toolbarEnd={toolbarActions ? <>{toolbarEnd}{toolbarActions}</> : toolbarEnd}
      scrollTop={session?.scrollPositions?.components ?? 0}
      onScrollTopChange={mapId ? (next) => setMapScroll(mapId, "components", next) : undefined}
    >
      {body}
    </ControllerView>
  )
}
